1: //! resume / fork（docs/04 §3.1，SH-031）。
2: //!
3: //! resume 的本质是"把档案重放成运行时的 `history`"，因此它的正确性判据只有一条：
4: //! **重放出来的历史必须能直接喂给模型且不违反协议**。SH-082 已经证明，
5: //! 一条 `function_call` 后面缺配对的 `function_call_output`，严格端点直接 400——
6: //! 所以 fork 的截断点不能随便选，见 [`nearest_safe_cut`]。
7: 
8: use std::path::{Path, PathBuf};
9: use std::time::{SystemTime, UNIX_EPOCH};
10: 
11: use crate::model_client::{HistoryItem, Role};
12: use crate::rollout::{self, RolloutError, RolloutItem, RolloutWriter};
13: 
14: /// 重放出来的会话：档案元信息 + 可直接续用的历史 + 档案路径。
15: #[derive(Debug, Clone, PartialEq)]
16: pub struct Resumed {
17:     pub session_id: String,
18:     pub agent_id: String,
19:     pub parent_id: Option<String>,
20:     pub history: Vec<HistoryItem>,
21:     pub path: PathBuf,
22:     /// 会话建档时固化的工作区根（SH-099）：resume 时工具作用域跟随原目录。
23:     /// 旧档案没有该字段时是空串，调用方回落全局默认根。
24:     pub workspace_root: String,
25:     /// 档案里被应用的压缩锚点数（SH-032 落地后用于核对）。
26:     pub applied_compactions: usize,
27:     /// 会话内最后一次档位切换（无则 None = 跟随部署默认）。
28:     pub sandbox_mode: Option<String>,
29:     /// 档案里记录过的系统提示词版本（按写入顺序）。旧档案为空 = 未记录。
30:     pub prompt_versions: Vec<SystemPromptRecord>,
31:     /// 末行半截写被丢弃的行数。
32:     pub torn_tail_lines: usize,
33:     /// 中间坏行（已跳过）的 1-based 行号；空 = 档案完好。重放出来的历史因此可能缺条目。
34:     pub damaged_lines: Vec<usize>,
35: }
36: 
37: /// 档案里的一条系统提示词版本（只读快照，供审计与轨迹回放）。
38: #[derive(Debug, Clone, PartialEq, Eq)]
39: pub struct SystemPromptRecord {
40:     /// 落盘后的文本（写入时已经过统一脱敏）。
41:     pub text: String,
42:     pub sha256: String,
43:     pub at_ms: u64,
44:     pub turn: u32,
45: }
46: 
47: /// 重放档案 → 历史。
48: ///
49: /// `Compacted` 锚点按记录顺序就地生效：用 `[range_start, range_end)` 换成一条摘要
50: /// **user** 消息。
51: ///
52: /// 这里原本取的是 assistant，理由是"摘要是一个模型此前说过的话的浓缩，归 assistant
53: /// 语义最正"。**那个选择在 thinking 档下不成立**：端点要求重放的每条 assistant 消息
54: /// 都带回 `reasoning_content`（SH-083），而摘要没有这个字段，真机基线里任务因此直接
55: /// 400。语义上也站得住另一种读法——摘要是交给下一个模型的**交接指令**，不是复述旧回答。
56: /// codex 同此（`CompactionSummary::role()` 返回 "user"）。
57: ///
58: /// 不变量③（04 §6.1，系统提示每轮重算）禁止的是塞进 **system**，user 不受那条约束，
59: /// 所以当初那条论证真正排除的只有 system，并没有支持 assistant。
60: pub fn resume(path: &Path) -> Result<Resumed, RolloutError> {
61:     let archive = rollout::read(path)?;
62:     let (session_id, agent_id, parent_id, workspace_root) = match &archive.meta {
63:         RolloutItem::SessionMeta { session_id, agent_id, parent_id, config_snapshot, .. } => {
64:             (session_id.clone(), agent_id.clone(), parent_id.clone(), config_snapshot.workspace_root.clone())
65:         }
66:         // read() 已保证首行是 session_meta，这里不可达；留 debug_assert 而不是运行时兜底
67:         other => {
68:             debug_assert!(false, "read 应已拒绝非 meta 首行，收到 {other:?}");
69:             return Err(RolloutError::NoSessionMeta(format!("{}", path.display())));
70:         }
71:     };
72: 
73:     let mut history: Vec<HistoryItem> = Vec::new();
74:     let mut applied = 0usize;
75:     // 档位事件不进模型历史，只取最后一条作为本会话的当前档位。
76:     let mut sandbox_mode: Option<String> = None;
77:     // 系统提示词版本不进模型历史（每轮由 SessionPrompt 重新组装），只做审计与回放。
78:     let mut prompt_versions: Vec<SystemPromptRecord> = Vec::new();
79:     for item in &archive.items {
80:         match item {
81:             RolloutItem::ResponseItem { item: h, .. } => history.push(h.clone()),
82:             RolloutItem::SandboxMode { mode, .. } => sandbox_mode = Some(mode.clone()),
83:             RolloutItem::SystemPrompt { text, sha256, at_ms, turn } => {
84:                 // 自洽校验：档案被手工改动/写坏时，宁可拒绝 resume 也不能把它当真历史展示。
85:                 // 只校验"文本与指纹是否匹配"，不拿当前配置重算——那等于用推测覆盖事实。
86:                 let actual = rollout::sha256_hex(text);
87:                 if &actual != sha256 {
88:                     return Err(RolloutError::Corrupted {
89:                         line: 0,
90:                         message: format!(
91:                             "系统提示词行校验失败（sha256 不符；档案内记录 {sha256}，实算 {actual}）"
92:                         ),
93:                     });
94:                 }
95:                 prompt_versions.push(SystemPromptRecord {
96:                     text: text.clone(),
97:                     sha256: sha256.clone(),
98:                     at_ms: *at_ms,
99:                     turn: *turn,
100:                 });
101:             }
102:             RolloutItem::Compacted { range_start, range_end, summary } => {
103:                 let (start, end) = (*range_start, *range_end);
104:                 if end > history.len() || start > end {
105:                     return Err(RolloutError::Corrupted {
106:                         line: 0,
107:                         message: format!(
108:                             "压缩锚点区间 [{start},{end}) 超出已重放长度 {}",
109:                             history.len()
110:                         ),
111:                     });
112:                 }
113:                 let summary_item = HistoryItem::Message {
114:                     // 摘要取 **user** 角色，不是 assistant：thinking 档要求重放的每条
115:                     // assistant 消息都带 `reasoning_content`（SH-083），摘要没有那个字段，
116:                     // 以 assistant 身份进历史会被端点直接 400。04 §6.1 不变量③ 禁的是塞进
117:                     // system，user 不受那条约束；codex 的 `CompactionSummary::role()` 同样是 "user"。
118:                     role: Role::User,
119:                     text: summary.clone(),
120:                     reasoning: None,
121:                 };
122:                 history.splice(start..end, [summary_item]);
123:                 applied += 1;
124:             }
125:             RolloutItem::SubagentRef { .. } => {
126:                 // 子代理引用不进父会话历史；整树 replay 是 SH-056 的范围
127:             }
128:             RolloutItem::AbortNote { reason, .. } => {
129:                 // 退出等待超时的强制中止留痕：不进模型历史，但必须在日志里看得见，
130:                 // 否则“档案为什么断在这里”又变成无人能解释。
131:                 tracing::warn!("会话档案含强制中止记录：{reason}");
132:             }
133:             RolloutItem::TurnEnd { reason, .. } => {
134:                 // 结局只服务于导出/统计/审计，不参与模型历史重建。
135:                 tracing::debug!("会话档案回合结局：{reason}");
136:             }
137:             RolloutItem::SessionMeta { .. } => {
138:                 return Err(RolloutError::Corrupted {
139:                     line: 0,
140:                     message: "档案主体中不应再出现 session_meta".into(),
141:                 });
142:             }
143:         }
144:     }
145: 
146:     Ok(Resumed {
147:         session_id,
148:         agent_id,
149:         parent_id,
150:         history,
151:         path: path.to_path_buf(),
152:         workspace_root,
153:         applied_compactions: applied,
154:         sandbox_mode,
155:         prompt_versions,
156:         torn_tail_lines: archive.torn_tail_lines,
157:         damaged_lines: archive.damaged_lines,
158:     })
159: }
