161: /// 从 `want` 往下找最近一个**安全截断点**：该位置之前的历史里，每个 `function_call`
162: /// 都有配对的 `function_call_output`。
163: ///
164: /// 为什么不能直接按用户选的条数切：一轮的工具记录是"先全部 call、再全部 output"，
165: /// 从中间截断就会留下有 call 无 output 的尾巴，续写出来的会话第一次请求就 400。
166: /// 安全点必然落在某轮工具段开始之前，也就是索引处是 `message`（或干脆到末尾）。
167: pub fn nearest_safe_cut(items: &[RolloutItem], want: usize) -> usize {
168:     let want = want.min(items.len());
169:     // 从 want 往下逐个试：[0, k) 是否配对完整
170:     for k in (0..=want).rev() {
171:         if paired_prefix(&items[..k]) {
172:             return k;
173:         }
174:     }
175:     0
176: }
177: 
178: fn paired_prefix(items: &[RolloutItem]) -> bool {
179:     let mut calls: Vec<&str> = Vec::new();
180:     let mut outputs: Vec<&str> = Vec::new();
181:     for item in items {
182:         match item {
183:             RolloutItem::ResponseItem { item: HistoryItem::FunctionCall { call_id, .. }, .. } => {
184:                 calls.push(call_id.as_str())
185:             }
186:             RolloutItem::ResponseItem {
187:                 item: HistoryItem::FunctionCallOutput { call_id, .. },
188:                 ..
189:             } => {
190:                 outputs.push(call_id.as_str())
191:             }
192:             _ => {}
193:         }
194:     }
195:     calls.iter().all(|c| outputs.contains(c)) && outputs.iter().all(|o| calls.contains(o))
196: }
