198: /// fork 的结果：新档案路径 + 实际采用的截断点 + 因不安全而被回退掉的条目数。
199: #[derive(Debug, Clone, PartialEq)]
200: pub struct Forked {
201:     pub path: PathBuf,
202:     pub new_agent_id: String,
203:     pub kept_items: usize,
204:     pub dropped_items: usize,
205: }
206: 
207: /// 复制档案到 `<dir>/<new_agent_id>.jsonl`，截断到最近安全点，并写入带 `parent_id` 的新首行。
208: ///
209: /// 原档案**只读**：fork 出错的代价不该由父会话的历史承担。
210: pub fn fork(src: &Path, dir: &Path, new_agent_id: &str, want_items: usize) -> Result<Forked, RolloutError> {
211:     let archive = rollout::read(src)?;
212:     let parent = match &archive.meta {
213:         RolloutItem::SessionMeta { agent_id, config_snapshot, .. } => (agent_id.clone(), config_snapshot.clone()),
214:         other => return Err(RolloutError::NoSessionMeta(format!("{:?}", other))),
215:     };
216:     let keep = nearest_safe_cut(&archive.items, want_items);
217:     std::fs::create_dir_all(dir).map_err(|e| RolloutError::Io(format!("{dir:?}: {e}")))?;
218:     let path = dir.join(format!("{new_agent_id}.jsonl"));
219:     let meta = RolloutItem::SessionMeta {
220:         session_id: new_agent_id.to_string(),
221:         agent_id: new_agent_id.to_string(),
222:         parent_id: Some(parent.0),
223:         created_at: SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_millis() as u64).unwrap_or_default(),
224:         config_snapshot: parent.1,
225:     };
226:     let writer = RolloutWriter::create(dir, &meta)?;
227:     for item in &archive.items[..keep] {
228:         writer.append(item)?;
229:     }
230:     Ok(Forked {
231:         path,
232:         new_agent_id: new_agent_id.to_string(),
233:         kept_items: keep,
234:         dropped_items: want_items.saturating_sub(keep),
235:     })
236: }
