152: impl RolloutWriter {
153:     /// 建档：创建 `<dir>/<agent_id>.jsonl` 并写入首行 SessionMeta。
154:     /// 已存在则拒绝——覆盖历史档案是不可逆的数据丢失，绝不静默进行。
155:     pub fn create(dir: &Path, meta: &RolloutItem) -> Result<Self, RolloutError> {
156:         let (_, file_name) = match meta {
157:             RolloutItem::SessionMeta { agent_id, .. } => (agent_id.clone(), format!("{agent_id}.jsonl")),
158:             other => return Err(RolloutError::NoSessionMeta(format!("建档首行必须是 session_meta，收到 {:?}", other))),
159:         };
160:         std::fs::create_dir_all(dir).map_err(|e| RolloutError::Io(format!("{dir:?}: {e}")))?;
161:         let path = dir.join(&file_name);
162:         let file = OpenOptions::new()
163:             .write(true)
164:             .create_new(true)
165:             .open(&path)
166:             .map_err(|e| {
167:                 if e.kind() == std::io::ErrorKind::AlreadyExists {
168:                     RolloutError::AlreadyExists(format!("{}", path.display()))
169:                 } else {
170:                     RolloutError::Io(format!("{path:?}: {e}"))
171:                 }
172:             })?;
173:         let writer = Self { path, file: Mutex::new(file) };
174:         writer.append(meta)?;
175:         Ok(writer)
176:     }
177: 
178:     /// 以追加方式重新打开已有档案（resume 用，SH-031）。
179:     ///
180:     /// 校验首行确实是 `session_meta` 才允许续写：往一个没有建档的文件里追加，
181:     /// 产出的是一份 resume 时才发现读不了的档案，错误被推迟到最难定位的时刻。
182:     pub fn open_existing(path: &Path) -> Result<Self, RolloutError> {
183:         let head = File::open(path)
184:             .map_err(|e| RolloutError::Io(format!("{path:?}: {e}")))?;
185:         let first_line = BufReader::new(head)
186:             .lines()
187:             .next()
188:             .ok_or_else(|| RolloutError::NoSessionMeta(format!("{}", path.display())))?
189:             .map_err(|e| RolloutError::Io(format!("{}", e)))?;
190:         let first: RolloutItem = serde_json::from_str(&first_line)
191:             .map_err(|e| RolloutError::Corrupted { line: 1, message: e.to_string() })?;
192:         if !matches!(first, RolloutItem::SessionMeta { .. }) {
193:             return Err(RolloutError::NoSessionMeta(format!("{}", path.display())));
194:         }
195:         let file = OpenOptions::new()
196:             .append(true)
197:             .open(path)
198:             .map_err(|e| RolloutError::Io(format!("{path:?}: {e}")))?;
199:         Ok(Self { path: path.to_path_buf(), file: Mutex::new(file) })
200:     }
201: 
202:     pub fn path(&self) -> &Path {
203:         &self.path
204:     }
