271: /// 读取档案。规则见文件头设计选择 2：中间坏行跳过但**记录并告警**，首行坏与末行撕裂
272: /// 分别按"没有 meta"与"半截写"处理。
273: pub fn read(path: &Path) -> Result<Rollout, RolloutError> {
274:     let file = File::open(path).map_err(|e| RolloutError::Io(format!("{path:?}: {e}")))?;
275:     let reader = BufReader::new(file);
276:     // 单行编码损坏（InvalidData）与"这一行 JSON 写坏了"同属可跳过的数据损坏，记为
277:     // 损坏行；其余 IO 错误是磁盘/句柄故障，跳过它会把后续行一起读歪，必须整份上报。
278:     // （审计 M6 防的是 `unwrap_or_default()` 把读错误变成空行再**悄悄**略过；这里的
279:     // 跳过是带行号计数的显式损坏，不是静默。）
280:     let mut raw_lines: Vec<Option<String>> = Vec::new();
281:     for line in reader.lines() {
282:         match line {
283:             Ok(text) => raw_lines.push(Some(text)),
284:             Err(e) if e.kind() == std::io::ErrorKind::InvalidData => raw_lines.push(None),
285:             Err(e) => return Err(RolloutError::Io(format!("{path:?}: {e}"))),
286:         }
287:     }
288: 
289:     // 半截写判定看**文件末尾有没有换行**，而不是看 JSON 能不能解析：
290:     // 崩溃时最后一段可能恰好是合法 JSON 的前缀，也可能碰巧完整——只有换行位置是可靠信号。
291:     let mut torn = 0usize;
292:     if !ends_newline(path) {
293:         match raw_lines.last() {
294:             Some(Some(text)) if text.trim().is_empty() => {
295:                 raw_lines.pop();
296:             }
297:             Some(_) => {
298:                 torn = 1;
299:                 raw_lines.pop();
300:             }
301:             None => {}
302:         }
303:     }
304: 
305:     let mut parsed: Vec<(usize, RolloutItem)> = Vec::new();
306:     let mut damaged: Vec<usize> = Vec::new();
307:     for (idx, line) in raw_lines.iter().enumerate() {
308:         let number = idx + 1;
309:         let Some(text) = line else {
310:             damaged.push(number);
311:             continue;
312:         };
313:         if text.trim().is_empty() {
314:             continue;
315:         }
316:         match serde_json::from_str::<RolloutItem>(text) {
317:             Ok(item) => parsed.push((number, item)),
318:             Err(e) => {
319:                 // 首行坏 = 没有 meta。跳过它只会把后面条目伪装成"一份没有开头的档案"，
320:                 // 读出来仍然不能用，所以这里保持硬失败。
321:                 if parsed.is_empty() {
322:                     return Err(RolloutError::Corrupted { line: number, message: e.to_string() });
323:                 }
324:             }
325:         }
326:     }
327: 
328:     let (first_line, meta) = parsed
329:         .first()
330:         .cloned()
331:         .ok_or_else(|| RolloutError::NoSessionMeta("文件为空".into()))?;
332:     if !matches!(meta, RolloutItem::SessionMeta { .. }) {
333:         return Err(RolloutError::NoSessionMeta(format!("第 {} 行", first_line)));
334:     }
335:     let items = parsed.into_iter().skip(1).map(|(_, item)| item).collect();
336:     if !damaged.is_empty() {
337:         // 唯一收口：所有调用方（打开会话、搜索对账、resume、fork）都经这里，
338:         // 不会出现"某个入口悄悄少了几条历史却没人知道"。
339:         tracing::warn!(
340:             path = %path.display(),
341:             count = damaged.len(),
342:             lines = %damaged.iter().map(usize::to_string).collect::<Vec<_>>().join(","),
343:             "rollout 含无法解析的行：已跳过并保留其余条目，这份历史可能不完整"
344:         );
345:     }
346:     Ok(Rollout { meta, items, torn_tail_lines: torn, damaged_lines: damaged })
347: }
