401:                 if let Some(custom) = titles.get(&summary.agent_id) {
402:                     summary.title = custom.clone();
403:                 }
404:                 summary
405:             })
406:         })
407:         .collect();
408:     out.sort_by(|a, b| b.updated_at.cmp(&a.updated_at).then_with(|| a.agent_id.cmp(&b.agent_id)));
